window.SODA_DATA={actTitle:"Sale of Drugs Act 1952",regTitle:"Control of Drugs & Cosmetics Regulations 1984",
notes:{act:[{title:'Key provisions',items:[{t:'s.7',d:'Sampling: Officer divides sample into THREE parts (not four) — seller, analyst, retained.'},{t:'s.12',d:'Body Corporate — First offence: ≤RM50,000. Subsequent: ≤RM100,000.'},{t:'s.18(4)',d:'Proceedings must be instituted within 60 days of taking sample.'},{t:'s.20',d:'Written warranty defence — must be delivered to prosecutor within 7 days of summons.'}]},{title:'Who appoints what',items:[{t:'Analysts',d:'Appointed by Yang di-Pertuan Agong'},{t:'Officers/Inspectors',d:'Appointed by Chief Minister'}]}],reg:[{title:'DCA & Registration',items:[{t:'DCA Chairman',d:'Director-General of Health (ex officio)'},{t:'Secretary',d:'Public service pharmacist — NOT a voting DCA member'},{t:'Traditional medicine registration fee',d:'RM500'},{t:'Other product registration fee',d:'RM1,000'},{t:'Prohibited substances (Table II)',d:'Caffeine, Nicotinamide, Paracetamol in traditional medicines'},{t:'Heavy metals (Table I)',d:'Lead ≤10ppm, Arsenic ≤5ppm, Mercury ≤0.5ppm, Cadmium ≤0.3ppm'}]}],warn:['Sample divided into THREE parts — not four','Proceedings must begin within 60 days of sampling','Sanction to prosecute: NOT required under SODA (unlike MASA)','Secretary of DCA is NOT a member of the Authority']},
flashcards:[{q:'Who appoints Analysts under SODA?',a:'Yang di-Pertuan Agong',ref:'s.3(1) SODA 1952'},{q:'How many parts must a drug sample be divided into?',a:'Three parts (Seller, Analyst, Retained)',ref:'s.7(2) SODA 1952'},{q:'Time limit to institute proceedings after sampling?',a:'60 days',ref:'s.18(4) SODA 1952'},{q:'Traditional medicine registration fee?',a:'RM500',ref:'Reg 8(2)(a) CDCR 1984'},{q:'Maximum lead content in traditional medicine?',a:'10.0 ppm (mg/kg)',ref:'Table I CDCR 1984'},{q:'Is the Secretary of DCA a voting member?',a:'No — not a member of the Authority',ref:'Reg 3(7) CDCR 1984'}],
law:[{sec:'s.7(2)',title:'Sampling',body:'Divide sample into <span class="lh">three parts</span> — mark and seal, offer one to seller, deliver one to analyst, retain one.'},{sec:'s.12(2)',title:'Body Corporate penalty',body:'First offence: ≤ <span class="lh">RM50,000</span>. Second or subsequent: ≤ <span class="lh">RM100,000</span>.'},{sec:'s.18(4)',title:'Proceedings timeline',body:'No proceedings instituted after <span class="lh">sixty days</span> from date of purchase/procurement.'},{sec:'CDCR Tab II',title:'Traditional medicine prohibitions',body:'Prohibited: <span class="lh">Caffeine</span>, <span class="lh">Nicotinamide</span>, <span class="lh">Paracetamol</span>, and any Poison under PA 1952.'}],
questions:[
  {act:'SODA · CDCR',q:'Which statement is TRUE regarding the rejection or cancellation of product registration?',opts:['A. The Drug Control Authority can cancel the registration of any product at any time but must give reason.','B. Cancellation of the registration of any product shall similarly and at the same time affect any license issued related to that product.','C. Where a license relates to several registered products, suspension of one product affects the position of other registered products.','D. All of the above.'],ans:1,exp:'Reg 11(2) CDCR 1984: Cancellation of registration simultaneously affects any licence issued relating to that product.'},
  {act:'SODA · CDCR',q:'The following is/are the function and/or power of the Director of Pharmaceutical Services under the Regulations:',stmts:['i. Issue a written consent to any person who brings any product to Malaysia in transit.','ii. Keep and maintain a register of registered products.','iii. Exempt any person to manufacture any product solely for treatment of a life-threatening illness.','iv. Issue a certificate on any matter relating to any product if required by any importing country.'],opts:['A. i and ii only','B. i, iii and iv only','C. iii and iv only','D. All of the above'],ans:1,exp:'The register is maintained by the Secretary, not DPS. DPS handles transit consent (i ✓), life-threatening exemptions (iii ✓), and export certificates (iv ✓).'},
  {act:'SODA · CDCR',q:'The register of products kept by the Secretary of DCA must contain:',stmts:['i. The name under which the product is registered.','ii. The content and quantity of the active ingredients.','iii. The name and the address of the manufacturer.','iv. The name and address of the product registration holder.'],opts:['A. i, ii and iii only','B. ii, iii and iv only','C. i, iii and iv only','D. i, ii, iii and iv only'],ans:3,exp:'Reg 9(2) CDCR 1984: All four must be in the register.'},
  {act:'SODA · CDCR',q:'The following substances are prohibited in a traditional medicine preparation:',stmts:['i. Paracetamol','ii. Dexamethasone','iii. Caffeine','iv. Naturally-occurring theophylline in tea'],opts:['A. i, ii and iii only','B. ii, iii and iv only','C. iii and iv only','D. iv only'],ans:0,exp:'Table II CDCR 1984: Paracetamol (i ✓), Dexamethasone as a Poison (ii ✓), and Caffeine (iii ✓) are prohibited. Naturally-occurring theophylline in tea is not expressly banned (iv ✗).'},
  {act:'SODA · CDCR',q:'Which of the following are offences under Sale of Drugs Act 1952?',stmts:['i. Selling non-registered Tongkat Ali capsules.','ii. Supplying a mixture of a registered Tongkat Ali product with a registered Kacip Fatimah product.','iii. Possessing 1000 bottles of Tongkat Ali product whose registration has been suspended by the DCA.'],opts:['A. i, ii and iii only','B. i and iii only','C. i and ii only','D. ii and iii only'],ans:0,exp:'Reg 7 CDCR 1984: All three are offences — selling unregistered (i ✓), unauthorised mixing of two registered products (ii ✓), and possessing suspended products (iii ✓).'}
]};

