window.MASA_DATA={actTitle:"Medicine (Advertisement and Sale) Act 1956",regTitle:"Medicine Advertisements Board Regulations 1976",
notes:{act:[{title:'Prohibition framework',items:[{t:'s.3',d:'Totally prohibited — 20 scheduled diseases (Cancer, AIDS, Asthma, Diabetes, Hypertension, Drug Addiction, etc.)'},{t:'s.4',d:'Absolute prohibition on abortion advertisements'},{t:'s.4A',d:'Services relating to treatment/diagnosis — prohibited unless exempted'},{t:'s.4B',d:'All other medicine/remedy ads need MAB approval'},{t:'Authorized Officer',d:'Pharmacist in public service authorized in writing by Minister'},{t:'Sanction to prosecute',d:'REQUIRED — written sanction of Public Prosecutor (s.6F)'}]},{title:'MAB — r.3',items:[{t:'Chairman',d:'Director-General of Health'},{t:'Quorum',d:'3 members including Chairman'},{t:'Secretary',d:'Pharmacist in public service — non-voting'},{t:'Application fee',d:'RM300 (non-refundable)'}]}],reg:[],warn:['Abortion ads are absolutely prohibited — MAB CANNOT approve them','Authorized officers appointed by Minister; prosecutions sanctioned by Public Prosecutor','MAB quorum is only 3 members','Scheduled disease ads prohibited even with MAB — MAB cannot override s.3']},
flashcards:[{q:'Definition of advertisement under MASA?',a:'Includes notice, circular, report, label, wrapper, and oral announcements',ref:'s.2 MASA 1956'},{q:'Can you advertise a cure for Asthma?',a:'No — Asthma is listed in the s.3 Schedule',ref:'MASA s.3'},{q:'Are abortion ads ever permitted if approved by MAB?',a:'No — absolute prohibition',ref:'s.4 MASA 1956'},{q:'Who must sanction prosecution under MASA?',a:'Public Prosecutor — written sanction required',ref:'s.6F(1) MASA 1956'},{q:'MAB application fee?',a:'RM300 (non-refundable)',ref:'MAB Regs r.8'},{q:'Chairman of Medicine Advertisements Board?',a:'Director General of Health',ref:'MAB Reg 3(1)'},{q:'Quorum for MAB meeting?',a:'Three members',ref:'MAB Reg 3(2)'}],
law:[{sec:'s.3',title:'Scheduled disease prohibition',body:'No person shall take any part in publication of advertisement for prevention or treatment of diseases specified in the <span class="lh">Schedule</span>.'},{sec:'s.4',title:'Abortion prohibition',body:'No person shall publish any advertisement referring to any article in terms calculated to lead to its use for <span class="lh">procuring the miscarriage</span> of women.'},{sec:'s.6F(1)',title:'Sanction to prosecute',body:'No prosecution shall be instituted without the <span class="lk">sanction in writing</span> of the <span class="lh">Public Prosecutor</span>.'},{sec:'MAB Reg 3',title:'Board proceedings',body:'Chairman = DG Health. Quorum = <span class="lh">three members</span> including Chairman.'}],
questions:[
  {act:'MASA · s.2',q:'This Act prohibits certain advertisement related to medical services which include the following materials:',opts:['A. Pamphlet or brochure','B. Label','C. Any announcement made orally','D. All of the above.'],ans:3,exp:'s.2 MASA 1956 defines advertisement broadly to include pamphlets, labels, and oral announcements.'},
  {act:'MASA · s.4A',q:'A traditional practitioner advertises his service related to the treatment of hypertension.',opts:['A. This action contravenes Section 3.','B. This action contravenes Section 4A.','C. This is allowed if approved by the Medicine Advertisement Board.','D. This is allowed if approved by the Minister.'],ans:1,exp:'It contravenes Section 4A because it refers to a skill or service relating to treatment of a disease.'},
  {act:'MASA · s.3 / s.4A',q:'The publication of this advertisement contains element(s) that contravenes this Act:',stmts:['i. An invitation to seek service relating to ailment.','ii. The provision of free treatment by the company.','iii. Informing that the company provides treatment of sinusitis.','iv. Informing the symptoms of sinusitis.'],opts:['A. I only','B. I and II only','C. I and III only','D. III and IV only'],ans:2,exp:'Inviting services for an ailment (i) and advertising treatment for sinusitis (iii) directly contravene MASA.'},
  {act:'MASA · s.6B',q:'The following person may investigate any offences under the Medicines (Advertisement and Sale) Act 1956:',opts:['A. Drug Enforcement Officer','B. Authorized Officer','C. Senior officer of Customs','D. Police officer not below the rank of sub-Inspector'],ans:1,exp:'s.6B MASA 1956: Powers of investigation given specifically to an "Authorized Officer".'},
  {act:'MASA · s.3',q:'Mr. Z intends to publish an advertisement for a juice claiming to prevent ZIKA virus. The following statement is TRUE:',opts:['A. He may publish the advertisement after obtaining approval from the Medicine Advertisements Board.','B. The advertisement is totally prohibited.','C. A private clinic operated by a registered medical practitioner may advertise without MAB approval.','D. There is no offence if the advertiser publishes without approval.'],ans:0,exp:'ZIKA is not in the 20 absolutely prohibited diseases (s.3 Schedule). It may be published ONLY after obtaining MAB approval.'},
  {act:'MASA · s.3 / s.4A',q:'An advertisement relating to the following may be approved by the Medicine Advertisements Board:',stmts:['i. Registered supplements to relieve symptoms of osteoarthritis.','ii. Herbal medicine to improve the conditions of human kidney function.','iii. Services relating to the treatment of mental disorders by a private hospital.','iv. Services relating to the treatment of osteoarthritis by a traditional practitioner.'],opts:['A. I only','B. I and III only','C. II and III only','D. All of the above'],ans:1,exp:'Osteoarthritis supplements (i) can be approved by MAB. Private hospital mental disorder services (iii) may be exempted under s.4A. Kidney function herbal and traditional practitioner treatment of osteoarthritis are more restricted.'},
  {act:'MASA · MAB Reg',q:'The advertisement approval is issued:',stmts:['i. by the Board.','ii. by the chairman of the Board.','iii. according to the language to be used.','iv. to a website which is registered in another country.'],opts:['A. I only','B. III only','C. I and III only','D. II and IV only'],ans:2,exp:'Approvals are issued by the Board (MAB) (i ✓) and assessed according to the language used (iii ✓).'},
  {act:'MASA · s.6B',q:'Powers of the authorized officer under MASA include:',stmts:['i. requiring witnesses to attend before himself by writing (journey not more than 12km from home).','ii. recording statements from suspected offenders and witnesses.','iii. entering any premises where offence under the Act has been committed.','iv. arresting the suspected offenders.'],opts:['A. i, ii and iii','B. i, ii and iv','C. iii and iv','D. i, ii, iii and iv'],ans:3,exp:'s.6B MASA 1956: All four powers are granted to the Authorized Officer.'},
  {act:'MASA · s.3(2)',q:'A pharmaceutical company published an advertisement for Toconale cream for topical fungal infection without MAB approval. It shall be a defence to prove the advertisement was published in:',stmts:['i. the form of a poster meant for registered medical practitioners only.','ii. the annual book of a nursing college for the students.','iii. a monthly bulletin of a school of pharmacy for undergraduate students.','iv. a bulletin meant for registered veterinary surgeons only.'],opts:['A. i, ii and iii','B. i and iii','C. i and iv','D. i, ii, iii and iv'],ans:3,exp:'s.3(2) MASA 1956: Professional/educational circulation to healthcare professionals (medical practitioners, nursing students, pharmacy students, veterinary surgeons) is a valid defence.'},
  {act:'MASA · MAB Reg r.7',q:'The approval issued by the Medicine Advertisements Board shall:',stmts:['i. be subject to such terms and conditions.','ii. state the media to be used.','iii. contain the name of the applicant.','iv. contain the product registration number.'],opts:['A. i and ii','B. i, ii and iii','C. iii and iv','D. i, ii, iii and iv'],ans:1,exp:'MAB Reg 1976 Reg 7: Terms and conditions (i ✓), media specified (ii ✓), applicant name (iii ✓). Product registration number (iv) is not mandated in the approval itself.'},
  {act:'MASA · s.3 / s.4',q:'The following is a prohibition regarding publication of advertisement under MASA:',stmts:['i. Any article which leads to use as medicine for prevention of AIDS.','ii. Misai Kucing capsule to treat hypertension.','iii. Misai Kucing capsule to treat hypertension after consulting the MAB.','iv. As medicine to treat asthma.'],opts:['A. i and iv','B. ii and iii','C. i, ii and iv','D. i, ii, iii and iv'],ans:3,exp:'MASA 1956: AIDS (i ✓), hypertension (ii ✓), hypertension WITH MAB approval (iii ✓ — MAB cannot override s.3 absolute prohibition), asthma (iv ✓) — all are prohibited.'},
  {act:'MASA · s.3',q:'The publication of any advertisement on diseases in the Schedule (Section 3) is prohibited EXCEPT by:',opts:['A. a person authorised by the Minister.','B. registered pharmacist.','C. the Malaysian Pharmaceutical Society.','D. the Malaysian Medical Council.'],ans:0,exp:'s.3(1) MASA 1956: Only persons specifically authorised by the Minister are excepted. No automatic exemption for pharmacists, MPS, or MMC.'},
  {act:'MASA · s.6F',q:'The following are TRUE regarding the Medicines (Advertisement and Sale) Act 1956:',stmts:['i. An authorized officer is a pharmacist in the public service authorized in writing by the Minister.','ii. No prosecution shall be instituted without the written sanction of the Public Prosecutor.','iii. The approval serial number and expiry date shall be legibly displayed in every approved print advertisement.','iv. The quorum for a Medicine Advertisements Board meeting is five members.'],opts:['A. i and ii','B. i, ii and iii','C. ii, iii and iv','D. i, ii, iii and iv'],ans:1,exp:'MASA + MAB Reg: Authorized officer definition (i ✓), sanction required (ii ✓), serial number + expiry on print ads (iii ✓). MAB quorum is THREE — not five (iv ✗).'},
  {act:'MASA · s.4 / s.4A',q:'In relation to prohibition of advertisement under MASA, no person shall take part in the publication of:',stmts:['i. a report on a medicine to improve functioning of the human heart.','ii. an advertisement for abortion.','iii. a medicine advertisement for treatment of a skin disease.','iv. any service relating to the treatment of certain disease by a private clinic.'],opts:['A. i and ii','B. iii and iv','C. i, ii, iii and iv','D. None of the above'],ans:2,exp:'MASA 1956: Heart disease on Schedule (i ✓ — prohibited). Abortion absolute prohibition s.4 (ii ✓). Skin disease — likely not on Schedule but needs MAB approval; if framed as disease treatment without approval (iii ✓). Private clinic services s.4A (iv ✓ unless exempted). Most sources indicate all four.'}
]};
