window.DDA_DATA={actTitle:"Dangerous Drugs Act 1952",regTitle:"Dangerous Drugs Regulations 1952",
notes:{act:[{title:'Trafficking thresholds — s.37(da)',items:[{t:'Heroin/Morphine',d:'15 grammes'},{t:'Cocaine',d:'40 grammes'},{t:'Amphetamine/Methamphetamine/MDMA',d:'50 grammes'},{t:'Cannabis/Cannabis resin',d:'200 grammes'},{t:'Raw Opium/Prepared Opium',d:'1,000 grammes'}]},{title:'Key penalties',items:[{t:'Trafficking [s.39B]',d:'Death or life imprisonment + whipping ≥12 strokes'},{t:'Planting/Cultivating [s.6B]',d:'Life imprisonment + whipping ≥6 strokes'},{t:'Self Administration [s.15]',d:'Fine ≤RM5,000 or ≤2 years imprisonment'}]}],reg:[{title:'Records & Registers',items:[{t:'Supply of morphine in clinic',d:'Recorded in Prescription Book for dispensed medicines'},{t:'Register preservation',d:'2 years from last entry'},{t:'Third Schedule',d:'Exempted preparations — still subject to Reg 15(8) and Reg 16'},{t:'No cancellation',d:'No cancellation or obliteration in register — corrections by marginal note'}]}],warn:['Buprenorphine and Diazepam are PSYCHOTROPICS — not strictly DDA','Heroin, Morphine, Cannabis, Cocaine are strictly Dangerous Drugs','Register preservation: 2 years from last entry','Trafficking penalties: ≥12 strokes whipping. Cultivation: ≥6 strokes']},
flashcards:[{q:'Trafficking threshold for Heroin or Morphine?',a:'15 grammes',ref:'s.37(da) DDA'},{q:'Trafficking threshold for Cannabis?',a:'200 grammes',ref:'s.37(da) DDA'},{q:'Trafficking threshold for Cocaine?',a:'40 grammes',ref:'s.37(da) DDA'},{q:'Penalty for trafficking?',a:'Death or life imprisonment + ≥12 strokes whipping',ref:'s.39B DDA'},{q:'Penalty for planting cannabis?',a:'Life imprisonment + ≥6 strokes whipping',ref:'s.6B DDA'},{q:'Where should dispensing of morphine in a health clinic be recorded?',a:'Prescription Book for dispensed medicines',ref:'DDA Regulations'},{q:'Is Buprenorphine a Dangerous Drug?',a:'No — it is a Psychotropic Substance',ref:'Poisons Act Schedules'},{q:'DDA register preservation period?',a:'2 years from last entry',ref:'DD Reg 1952'}],
law:[{sec:'s.37(da)',title:'Trafficking presumption',body:'Found in possession of ≥<span class="lh">15g</span> heroin/morphine; ≥<span class="lh">200g</span> cannabis; ≥<span class="lh">1,000g</span> raw opium — presumed trafficking.'},{sec:'s.39B',title:'Trafficking penalty',body:'<span class="lk">Death or life imprisonment</span> + whipping ≥<span class="lh">12 strokes</span>.'},{sec:'s.6B',title:'Cultivating',body:'<span class="lk">Life imprisonment</span> + whipping ≥<span class="lh">6 strokes</span>.'},{sec:'s.15',title:'Self-administration',body:'Fine ≤<span class="lh">RM5,000</span> or imprisonment ≤<span class="lh">2 years</span>.'}],
questions:[
  {act:'DDA · s.25 / PA · s.8',q:'An international traveller can bring medicines into Malaysia for personal use subject to these Acts and regulations:',stmts:['i. Section 25 Dangerous Drugs Act 1952.','ii. Section 8(2) Poisons Act 1952.','iii. Regulation 4(2)(a) Poisons (Psychotropic Substances) Regulations 1989.','iv. Regulation 7(1A) Control of Drugs and Cosmetics Regulations 1984.'],opts:['A. i, ii and iii only','B. i, iii and iv only','C. ii, iii and iv only','D. i, ii, iii and iv'],ans:3,exp:'All four frameworks govern personal import of medicines — DDA for dangerous drugs, PA for poisons, P(PS)R for psychotropics, CDCR for registered products.'},
  {act:'DDA · Classification',q:'The following substances/products are classified as dangerous drugs:',opts:['A. Morphine pulv., N-ethyl MDA, cannabis and heroin.','B. Morphine pulv., amphetamine, cannabis and diazepam.','C. Morphine pulv., dextromethorphan, cannabis and heroin.','D. Morphine injection, dextromethorphan, cannabis and heroin.'],ans:0,exp:'Morphine, N-ethyl MDA, cannabis, and heroin are all strictly Dangerous Drugs. Diazepam is a psychotropic. Dextromethorphan is not a DD.'},
  {act:'DDA · s.37(da)',q:'Any person found in possession of the following shall be presumed to be trafficking:',stmts:['i. 41 grammes of cocaine.','ii. 250 grammes of cannabis.','iii. 900 grammes of raw opium.','iv. a mixture containing 25 grammes of amphetamine and 25 grammes of methamphetamine.'],opts:['A. i, ii and iii only','B. i, ii and iv only','C. i, iii and iv only','D. ii, iii and iv only'],ans:1,exp:'Thresholds: Cocaine 40g (41g ≥40g ✓ i), Cannabis 200g (250g ≥200g ✓ ii), Raw opium 1000g (900g <1000g ✗ iii), Amphetamine mix 50g (25+25=50g ≥50g ✓ iv). Correct: i, ii and iv.'},
  {act:'P(PS)R · r.19',q:'Upho Berhad manufactures pethidine injection. Choose the CORRECT statements:',stmts:['i. A register called "Production Register for Psychotropic Substance" shall be kept.','ii. The manufacturing date must be entered in the register.','iii. The pharmaceutical dosage form can be omitted from the register.','iv. A separate register shall be used for each type of psychotropic substance.'],opts:['A. i and ii only','B. i, ii and iv only','C. iii and iv only','D. i, ii, iii and iv'],ans:1,exp:'P(PS)R Reg 19-21: Production Register must be kept (i ✓), manufacturing date required (ii ✓), separate register for each type (iv ✓). Dosage form CANNOT be omitted (iii ✗).'},
  {act:'DD Reg · r.15',q:'The following statement(s) is/are FALSE regarding the person dispensing a dangerous drug prescription:',stmts:['i. At the time of dispensing, shall mark on the prescription the MINUTE on which it is dispensed.','ii. Shall retain and keep the prescription on the premises where it is dispensed.','iii. Failure to produce the prescription upon inspection shall be guilty and liable to a fine not more than two thousand dollars.'],opts:['A. i, ii and iii only','B. i and ii only','C. iii only','D. i and iii only'],ans:3,exp:'DD Reg 1952: The dispenser shall mark the DAY — not the MINUTE (i is FALSE). Retaining prescription is REQUIRED (ii is TRUE). The fine is in RINGGIT not dollars, and the stated amount may be incorrect (iii is FALSE). False statements: i and iii.'},
  {act:'P(PS)R · r.11',q:'Every prescription for Benzodiazepine 2.5 mg/tablet prescribed by a registered medical practitioner shall:',stmts:['i. be in writing, signed and dated by the prescriber.','ii. state the name, identity card number and address of the patient.','iii. indicate the total amount of medicine to be supplied and the dose.','iv. state the address of the prescriber.'],opts:['A. ii and iii','B. i and iv','C. i, iii and iv','D. i, ii, iii and iv'],ans:3,exp:'Reg 11 P(PS)R 1989: All four requirements apply for psychotropic prescriptions.'},
  {act:'P(PS)R · r.15',q:'The Licensing Officer may issue a permit to purchase and use methadone to a:',stmts:['i. holder of Type A licence.','ii. registered dentist Division I.','iii. registered medical practitioner.','iv. game warden.'],opts:['A. i, ii and iii','B. ii, iii and iv','C. ii and iii','D. i, ii, iii and iv'],ans:0,exp:'Reg 15 P(PS)R 1989: Permit may be issued to Type A licence holder (i ✓), Dentist Div I for dental use (ii ✓), and registered medical practitioner (iii ✓). Game warden has no basis (iv ✗).'},
  {act:'DD Reg · r.6',q:'A registered pharmacist dealing with products in the Third Schedule shall:',stmts:['i. record in the day book or separate book on the day of any sale.','ii. enter in the Register true particulars with respect to every drug used in manufacturing.','iii. preserve all registers for a period of two years from the date the last entry is made.','iv. have a wholesale licence as specified in Regulation 18.'],opts:['A. i, ii, iii and iv','B. i, ii and iii','C. i and iv','D. ii and iii'],ans:1,exp:'DD Reg 1952: Daily recording (i ✓), register entries for manufacturing (ii ✓), 2 years preservation (iii ✓). Wholesale licence NOT specifically required for Third Schedule products (iv ✗).'},
  {act:'DD Reg · r.11',q:'Lomotil® containing diphenoxylate 2.5mg, registered under CDCR 1984:',opts:['A. may be supplied according to Section 21(2) Poisons Act 1952.','B. may be supplied according to Regulation 11(2) of Poisons (Psychotropic Substance) Regulations 1989.','C. may be supplied according to Regulation 11(2) of Dangerous Drug Regulations 1952.','D. may be dispensed without a prescription by a Licensed Pharmacist.'],ans:2,exp:'Diphenoxylate is a dangerous drug substance. Lomotil formulation (diphenoxylate + atropine) may be an exempted Third Schedule preparation — supply follows Reg 11(2) DD Regulations 1952.'},
  {act:'DD Reg · r.8',q:'The following presumptions is/are TRUE with reference to the Dangerous Drugs Regulations 1952:',stmts:['i. A person authorised to manufacture a drug shall be deemed to be authorised to supply that drug.','ii. A person authorised to supply a drug shall be deemed to be a person authorised to be in possession of that drug, to procure, to offer, to supply and to advertise for sale.','iii. A person authorised to supply a drug by way of wholesale dealing shall be deemed authorised to supply to persons in specified classes.'],opts:['A. i only','B. ii and iii','C. i and iii','D. i, ii and iii'],ans:3,exp:'DD Reg 1952 Reg 8: All three presumptions are explicitly provided for.'},
  {act:'DD Reg · r.15',q:'A product containing any substance specified in the Third Schedule of the Dangerous Drugs Regulations 1952 is exempted from:',opts:['A. any provision of Dangerous Drugs Regulations 1952 except paragraph (8) of regulation 15 and regulation 16.','B. paragraph (8) of regulation 15 and regulation 16 only.','C. any provision of Dangerous Drugs Act 1952.','D. any provision of Dangerous Drugs Regulation 1952.'],ans:0,exp:'DD Reg 1952 Reg 15: Third Schedule products are exempted from ALL DD Regulations EXCEPT Reg 15(8) and Regulation 16.'},
  {act:'DDA · s.37(da)',q:'Any person found in possession of Dangerous Drugs below shall be presumed to be trafficking:',stmts:['i. 15 grammes or more in weight of heroin.','ii. 15 grammes or more in weight of morphine.','iii. 15 grammes or more in weight of cocaine.','iv. a mixture containing 15 grammes of amphetamine and 35 grammes of 2,5-dimethoxyamphetamine.'],opts:['A. i, ii and iii only','B. i, ii and iv only','C. ii, iii and iv only','D. i, ii, iii and iv'],ans:1,exp:'s.37(da) DDA: Heroin ≥15g (i ✓), Morphine ≥15g (ii ✓), Cocaine threshold is 40g so 15g cocaine does NOT trigger presumption (iii ✗), Amphetamine mix 15+35=50g meets ≥50g threshold (iv ✓). Correct: i, ii and iv.'},
  {act:'DD Reg · r.15',q:'Which statements are TRUE regarding the keeping of the register for morphine sulphate?',stmts:['i. A separate register or a separate part of the register shall be used.','ii. No cancellation and obliteration shall be made of an entry in the register.','iii. Any correction of an entry must be made by way of a marginal note or footnote.','iv. The register shall be preserved for a period of one year from the last entry in the register.'],opts:['A. i and ii only','B. i, ii and iv only','C. iii and iv only','D. i, ii, iii and iv'],ans:0,exp:'DD Reg 1952: Separate register (i ✓), no cancellation (ii ✓). Correction by marginal note (iii ✓ also). Register preserved for 2 years — NOT 1 year (iv ✗). Correct: i, ii (and iii if listed — verify answer key).'},
  {act:'DDA · DD Reg',q:'The supply of registered morphine tablets in a government health clinic for medical treatment shall be recorded in:',opts:['A. Day Book for Dangerous Drugs.','B. Prescription Book for dispensed medicines.','C. Prescription Register for Psychotropic substances.','D. Poison Book for Group D Poisons.'],ans:1,exp:'For medical treatment dispensing in a health clinic, the supply of morphine is recorded in the Prescription Book for dispensed medicines.'},
  {act:'DDA · s.37(da)',q:'The following substances/products are classified as dangerous drugs:',opts:['A. Morphine pulv., pethidine, cannabis and heroin.','B. Morphine pulv., pethidine, cannabis and diazepam.','C. Morphine pulv., dextromethorphan, cannabis and heroin.','D. Morphine injection, dextromethorphan, cannabis and heroin.'],ans:0,exp:'Morphine, pethidine, cannabis, and heroin are all dangerous drugs. Diazepam is a psychotropic; dextromethorphan is not a dangerous drug.'},
  {act:'P(PS)R · r.27',q:'The sale of 2000 tablets Valium® 2.5 mg by a Licensed Pharmacist to another Licensed Pharmacist must be labelled according to:',opts:['A. Regulation 12 Poisons Act.','B. Regulation 14 Dangerous Drug Act.','C. Regulation 27 Poisons (Psychotropic Substances) Regulations 1989.','D. Regulation 28, Poisons (Psychotropic Substances) Regulations 1989.'],ans:2,exp:'Diazepam (Valium) is a psychotropic substance. Labelling requirements for supply between licensed pharmacists are governed by Regulation 27 P(PS)R 1989.'}
]};
// ── ETHICS DATA (16 questions) ────────────────────────────────────
window.ETHICS_DATA={actTitle:"Code of Ethics for Pharmacists 2018",regTitle:"Guidance & Disciplinary Procedure (RPA 1951)",
notes:{act:[{title:'The 7 Principles',items:[{t:'Principle 1',d:'Make patients your first concern'},{t:'Principle 2',d:'Use professional judgement in the interests of patients and the public'},{t:'Principle 3',d:'Show respect for others. Protect dignity, privacy and confidentiality'},{t:'Principle 4',d:'Encourage patients and the public to participate in decisions about their care'},{t:'Principle 5',d:'Develop your professional knowledge and competence'},{t:'Principle 6',d:'Be ethical, honest and trustworthy'},{t:'Principle 7',d:'Be responsible of your working practices'}]}],reg:[{title:'Disciplinary grounds — s.17(1)',items:[{t:'s.17(1)(a)',d:'Obtained registration by fraudulent or incorrect statement'},{t:'s.17(1)(b)',d:'Convicted of offence rendering unfit'},{t:'s.17(1)(c)',d:'Guilty of infamous or disgraceful conduct in a professional sense'}]},{title:'Punishments — s.18A',items:[{t:'Removal',d:'Name removed from register permanently'},{t:'Suspension',d:'Suspended for period determined by Board'},{t:'Reprimand',d:'Formal reprimand recorded'},{t:'NO fines',d:'Board cannot impose fines — fines are court-imposed only'},{t:'Appeal',d:'To the Minister — decision is FINAL'}]}],warn:['PATIENTS are first concern — not health professionals, not the public service','Confidential information can only be disclosed without consent if REQUIRED BY LAW','Board punishments under s.18A do NOT include fines','Appeal goes to MINISTER — not courts','P7: Cannot advertise for professional advantage beyond what legislation permits']},
flashcards:[{q:'What is Principle 1?',a:'Make patients your first concern',ref:'Code of Ethics 2018'},{q:'What is Principle 3?',a:'Show respect for others — protect dignity, privacy and confidentiality',ref:'Code of Ethics 2018'},{q:'What is Principle 6?',a:'Be ethical, honest and trustworthy',ref:'Code of Ethics 2018'},{q:'Can the Pharmacy Board impose a fine?',a:'No — Board can only remove, suspend, or reprimand. Fines are court-imposed.',ref:'s.18A RPA 1951'},{q:'Where does an appeal from a Board punishment go?',a:'The Minister — decision is final',ref:'s.19 RPA 1951'},{q:'Three grounds for disciplinary proceedings?',a:'(a) Fraudulent registration (b) Criminal conviction (c) Infamous/disgraceful conduct',ref:'s.17(1) RPA 1951'}],
law:[{sec:'Pr. 3',title:'Respect',body:'Never disclose confidential information without consent <span class="lh">unless required by law</span>.'},{sec:'s.17(1)',title:'Grounds for proceedings',body:'(a) <span class="lh">Fraudulent registration</span>; (b) <span class="lh">Criminal conviction</span>; (c) <span class="lh">Infamous or disgraceful conduct</span> in a professional sense.'},{sec:'s.18A',title:'Punishments',body:'<span class="lh">Remove</span> / <span class="lk">Suspend</span> / <span class="lk">Reprimand</span>. <span class="lh">No financial fine</span> by the Board.'},{sec:'s.19',title:'Appeal',body:'Appeal to the <span class="lk">Minister</span> — decision is <span class="lh">final</span>.'}],
questions:[
  {act:'ETHICS · Pr.1',q:'Which of the following statements is FALSE based on the Code of Ethics for Pharmacists?',opts:['A. A pharmacist must accept diversity and respect cultural differences.','B. A pharmacist must disclose a patient\'s profile to a medical doctor who is looking for a new customer.','C. A pharmacist must respect people\'s dignity, privacy, and confidentiality.','D. A pharmacist must treat people fairly and ensure their views about belief, race and gender do not affect their professional services.'],ans:1,exp:'Principle 3: Disclosing patient profiles to a doctor for client prospecting is a severe breach of confidentiality.'},
  {act:'ETHICS · Principles',q:'Which of the following principles are described in the Code of Ethics for Pharmacists?',stmts:['i. Develop professional knowledge and competence.','ii. Show respect to others.','iii. Make health professional as the first concern.','iv. Disregard patients\' choices in treatment.'],opts:['A. i and ii only','B. ii and iii only','C. i, ii and iii only','D. i, iii and iv'],ans:0,exp:'Principle 1 states PATIENTS are the first concern — not health professionals (iii ✗). Principle 4 says to respect patient choices — not disregard them (iv ✗). Correct: i (P5) and ii (P3).'},
  {act:'ETHICS · Pr.2',q:'A pharmacist adjusts a patient\'s drug therapy dosage without informing the prescriber. Which principle does this breach?',opts:['A. Principle 1 — Make patients your first concern.','B. Principle 2 — Use professional judgement in the interests of patients.','C. Principle 3 — Show respect for others.','D. Principle 6 — Be ethical, honest and trustworthy.'],ans:1,exp:'Guidance on Principle 2(d): Failing to consult or notify the prescriber when making adjustments breaches professional judgement obligations.'},
  {act:'ETHICS · Pr.3',q:'A pharmacist\'s religious belief prevents her from dispensing a particular product. Under the Code of Ethics, she MUST:',opts:['A. Dispense the product regardless of her belief.','B. Refuse to dispense and offer no further assistance.','C. Explain her position and may refer patients to other providers.','D. Report the patient to the Pharmacy Board.'],ans:2,exp:'Principle 3.4: Where religious or moral beliefs prevent providing a service, the pharmacist must explain and may refer to another provider.'},
  {act:'ETHICS · Reg / Inquiry',q:'According to the Guidance on Code of Ethics, the Board can SUMMARILY DISMISS a complaint if:',stmts:['i. The name and address of the complainant is unknown.','ii. The facts do not constitute a matter under s.17(1) even if true.','iii. The accused pharmacist is found guilty.','iv. There is reasonable doubt about the truth of the complaint.'],opts:['A. i and ii only','B. i, ii and iv only','C. ii and iii only','D. i, ii, iii and iv'],ans:1,exp:'Summary dismissal if: complainant untraceable (i ✓), facts do not constitute a statutory matter (ii ✓), or reasonable doubt about truth (iv ✓). A guilty verdict is not a dismissal ground (iii ✗).'},
  {act:'ETHICS · s.18A',q:'The following are punishments the Pharmacy Board may impose after a disciplinary inquiry, EXCEPT:',opts:['A. Removal of name from the register.','B. Suspension from the register for a determined period.','C. A fine of not more than RM50,000.','D. A reprimand.'],ans:2,exp:'s.18A RPA 1951: The Board can remove, suspend, or reprimand. Fines are NOT a Board punishment — that is a court penalty.'},
  {act:'ETHICS · Pr.3',q:'Choose the FALSE statement with regards to the Code of Ethics for Pharmacists 2018:',opts:['A. Effective communication is important to understand patients\' needs.','B. Sufficient information should be provided to help patients improve their compliance towards medications.','C. Patients\' information should be shared with all healthcare providers.','D. Up to date information should be given to patients to ensure informed decisions can be made.'],ans:2,exp:'Principle 3 Code of Ethics 2018: Patient information shall NEVER be shared without consent unless required by law. Sharing with ALL healthcare providers indiscriminately is a breach of confidentiality.'},
  {act:'ETHICS · Pr.1 / 5 / 7',q:'Which of the following is TRUE regarding the Code of Conduct for Pharmacists 2018?',stmts:['i. Pharmacists should supply only medicines and health products that are safe, effective and of good quality.','ii. Pharmacists are allowed not to serve a patient due to his/her sexual orientation, or religion.','iii. Pharmacists should seek more than fair and reasonable remuneration for their professional services.','iv. Pharmacists should continuously improve their professional knowledge and skills.'],opts:['A. i, ii and iii','B. i and iii','C. i and iv','D. i, iii and iv'],ans:2,exp:'Code of Ethics 2018: Supplying safe, effective, quality products (Principle 7) (i ✓). Cannot refuse due to sexual orientation/religion — discrimination (ii ✗). Seeking more than fair remuneration contradicts Principle 6 (iii ✗). Continuously improving competence (Principle 5) (iv ✓). Correct: i and iv.'},
  {act:'ETHICS · s.18A',q:'Which of the following is TRUE regarding the Code of Ethics for Pharmacists 2018?',stmts:['i. The Code of Ethics for Pharmacists 2018 is a guideline under Section 13 of the Registration of Pharmacists Act 1951.','ii. A pharmacist who acts contrary to the Code of Ethics may be punished under Section 18A of the Act.','iii. Breaching the Code of Ethics is classified under the infamous or disgraceful conduct in a professional sense.','iv. The Code of Ethics is a primary legislation.'],opts:['A. ii and iii only','B. i, ii and iii only','C. ii, iii and iv only','D. All of the above'],ans:1,exp:'The Code of Ethics is a guideline under s.13 RPA 1951 (i ✓). Breach = guilty under s.17(1)(c) = infamous conduct = punishment under s.18A (ii ✓, iii ✓). It is NOT primary legislation (iv ✗).'},
  {act:'ETHICS · Pr.6',q:'According to the Code of Ethics, a pharmacist MUST:',stmts:['i. Declare any private interests that might affect professional decisions.','ii. Respond openly and honestly to complaints from patients.','iii. Exploit patients\' vulnerability to promote professional advantage.','iv. Share conflicts of interest with relevant authorities.'],opts:['A. i only','B. i, ii and iv only','C. i, ii, iii and iv','D. i and ii only'],ans:1,exp:'Principle 6 Code of Ethics 2018: Declare private interests (i ✓), respond honestly to complaints (ii ✓), disclose conflicts of interest (iv ✓). Exploiting vulnerability (iii ✗) explicitly violates Principle 6.'},
  {act:'GGM · Core Moral Values',q:'Which of the following are NOT among the four core moral values essential to good governance?',stmts:['i. Integrity','ii. Honesty','iii. Truth','iv. Justice'],opts:['A. i and ii','B. i, ii and iii','C. ii, iii and iv','D. iii and iv'],ans:0,exp:'GGM Framework: The 4 CORE MORAL VALUES are Justice, Truth, Service to Common Good, Trusteeship. Integrity and Honesty are CODE OF CONDUCT VALUES for public servants — NOT core moral values.'},
  {act:'GGM · Appendix 4',q:'The following are unethical practices that may lead to corruption, based on Good Governance of Medicine:',stmts:['i. Allowing pseudo-trials of medicines to be carried out, funded by pharmaceutical companies, for marketing purposes.','ii. Taking the money made from the sale of medicines that were supposed to be supplied free of charge.','iii. Disclosing unethical practice and corruption to appropriate authorities.','iv. Selecting a specific medicine for the essential medicines list based on favour.'],opts:['A. i and ii','B. i, ii and iv','C. iii and iv','D. i, ii, iii and iv'],ans:1,exp:'GGM Framework: i (pseudo-trials ✓), ii (diverting funds ✓), iv (favouritism ✓) are unethical. iii (disclosing corruption) is an ETHICAL action.'},
  {act:'GGM · Objectives',q:'The objectives of the Good Governance Programme are to:',stmts:['i. inculcate and enhance integrity among public servants dealing in all areas involved in pharmaceuticals.','ii. promote transparency, accountability and ethical practices among health professionals in the public pharmaceutical sector.','iii. raise awareness of the potential for corruption in the pharmaceutical sector.','iv. minimise corruption by promoting and implementing good governance within the public pharmaceutical sector.'],opts:['A. i and ii','B. iii and iv','C. i, ii, iii and iv','D. None of the above'],ans:2,exp:'GGM Framework: All four are explicitly stated objectives of the GGM Programme.'},
  {act:'DUNas · Access',q:'The following are TRUE in the strategy to ensure access to medicine in MNMP, EXCEPT:',opts:['A. the implementation of generic medicine policy.','B. ensuring a rational medicine pricing system in the public and private sector.','C. strengthening the antimicrobial stewardships program.','D. ensuring safe and quality complementary medicine.'],ans:2,exp:'DUNas 4th Edition: Antimicrobial stewardship (C) falls under the QUALITY USE OF MEDICINES component — not the Access component. A, B, and D are Access strategies.'},
  {act:'DUNas · Components',q:'The following are the main components of the Malaysian National Medicine Policy (MNMP), EXCEPT:',opts:['A. quality use of medicine.','B. ability to access medicine.','C. safety, efficacy and quality of medicine.','D. governance in healthcare.'],ans:3,exp:'DUNas 4th Edition: The five components are (1) Governance in MEDICINES, (2) Quality Safety & Efficacy, (3) Access to Medicines, (4) Quality Use of Medicines, (5) Partnership & Collaboration. "Governance in HEALTHCARE" (D) is incorrectly stated — should be "in Medicines".'},
  {act:'ETHICS · Pr.6',q:'The following are TRUE regarding the pharmacist\'s ethical obligation in responding to adverse events or product-related issues:',stmts:['i. A pharmacist must acknowledge and seek to remedy errors or substandard services.','ii. A pharmacist should never report himself or a colleague to the Pharmacy Board.','iii. A pharmacist who provides false information is in breach of Principle 6.','iv. Remaining silent about an error to protect a colleague is acceptable if no patient harm occurred.'],opts:['A. i and iii only','B. i, ii and iii only','C. iii and iv only','D. i, ii, iii and iv'],ans:0,exp:'Principle 6 Code of Ethics 2018: Acknowledge and remedy errors (i ✓). Reporting to Board when warranted is a DUTY not forbidden (ii ✗). False information = breach of Principle 6 (iii ✓). Remaining silent to protect a colleague violates Principle 6 and Principle 2 (iv ✗).'}
]};
