window.GGM_DATA={actTitle:"Good Governance in Medicine (GGM)",regTitle:"Framework, Code of Conduct & Vulnerable Areas",
notes:{act:[{title:'GGM Overview',items:[{t:'Two Strategies',d:'DISCIPLINE-BASED (top-down: sanctions, ombudsman) + VALUES-BASED (bottom-up: ethics, code of conduct)'},{t:'4 Core Moral Values',d:'Justice, Truth, Service to the Common Good, Trusteeship'},{t:'Origin',d:'WHO GGM project — Malaysia was one of FIRST FOUR countries to participate (Phase 1: December 2004)'}]},{title:'4 Core Moral Values (Appendix 3)',items:[{t:'Justice',d:'Exercise of impartial judgement within the rule of law'},{t:'Truth',d:'Faithfulness to truth — basis of trustworthiness'},{t:'Service to Common Good',d:'Commitment to serve public interest — inclusive'},{t:'Trusteeship',d:'Public servants as trustworthy trustees — must disclose conflicts of interest'}]}],reg:[{title:'7 Code of Conduct Values',items:[{t:'Selflessness',d:'Decisions solely in public interest'},{t:'Integrity',d:'No financial or other obligations to outside individuals'},{t:'Objectivity',d:'Merit-based choices and appointments'},{t:'Accountability',d:'Accountable to the public for all decisions'},{t:'Openness',d:'Be as open as possible about decisions'},{t:'Honesty',d:'Declare private interests relating to public duties'},{t:'Leadership',d:'Promote these principles by example'}]},{title:'5 Vulnerable Areas (Appendix 2)',items:[{t:'Drug Registration',d:'Queue jumping, falsified data, bias in evaluation'},{t:'Inspection',d:'Bribery to alter compliance ratings'},{t:'Promotion',d:'Pharmaceutical company kickbacks, pseudo-trials'},{t:'Selection',d:'Selecting based on bribery rather than evidence'},{t:'Procurement',d:'Bid rigging, theft of medicines, cronyism'}]}],warn:['4 Core MORAL VALUES (Justice, Truth, Service to Common Good, Trusteeship) are DIFFERENT from 7 Code of Conduct VALUES','Malaysia was one of FIRST FOUR countries in WHO GGM project (Phase 1: December 2004)','GGM focuses on FIVE areas: Registration, Inspection, Promotion, Selection, Procurement','Both discipline-based AND values-based approaches must be integrated']},
flashcards:[{q:'What are the TWO strategic approaches in GGM?',a:'1. Values-based (bottom-up: ethics/code of conduct) 2. Discipline-based (top-down: sanctions/ombudsman)',ref:'GGM Framework'},{q:'List the 4 Core Moral Values.',a:'Justice, Truth, Service to the Common Good, Trusteeship',ref:'GGM Appendix 3'},{q:'List the 7 Code of Conduct Values.',a:'Selflessness, Integrity, Objectivity, Accountability, Openness, Honesty, Leadership',ref:'GGM Code of Conduct'},{q:'List the 5 GGM vulnerable areas.',a:'Registration, Inspection, Promotion, Selection, Procurement',ref:'GGM Appendix 2'},{q:'Malaysia role in WHO GGM project?',a:'One of the first four countries — Phase 1 assessment December 2004',ref:'GGM Preface'},{q:'What is the "Trusteeship" value?',a:'Public servants as trustworthy trustees of public resources — must disclose conflicts of interest',ref:'GGM Appendix 3'}],
law:[{sec:'Val.1',title:'Justice',body:'Exercise of <span class="lk">impartial</span> judgement within the framework of the <span class="lh">rule of law</span>.'},{sec:'Val.2',title:'Truth',body:'Faithfulness to truth is the basis of <span class="lk">trustworthiness</span>. Decisions must be based on <span class="lh">appropriate, reliable, provable evidence</span>.'},{sec:'Val.4',title:'Trusteeship',body:'Society expects public servants as <span class="lh">trustees</span> to be trustworthy. Must <span class="lk">disclose conflicts of interest</span>.'},{sec:'Areas',title:'5 Vulnerable Areas',body:'<span class="lk">Registration</span> — falsified data. <span class="lk">Inspection</span> — bribery. <span class="lk">Promotion</span> — kickbacks. <span class="lk">Selection</span> — bribery. <span class="lk">Procurement</span> — bid rigging.'}],
questions:[
  {act:'GGM · Framework',q:'Why is the pharmaceutical sector particularly vulnerable to corruption?',opts:['A. Low market interests.','B. Inappropriate incentive structures.','C. Less involvement by the government in its regulation.','D. Widely available information that helps in the assessment of quality, safety and efficacy of medicines.'],ans:1,exp:'GGM Framework: Vulnerability factors include high market volume, information imbalance, inappropriate incentive structures, poorly defined processes, and limited institutional checks.'},
  {act:'GGM · Code of Conduct',q:'Choose the values that conduct the behaviour of public servants, as described in the Framework for Good Governance in the Public Pharmaceutical Sector:',stmts:['i. Objectivity','ii. Accountability','iii. Honesty','iv. Openness'],opts:['A. i and iv only','B. ii and iii only','C. i, ii and iii only','D. i, ii, iii and iv'],ans:3,exp:'All four are among the 7 Code of Conduct Values: Selflessness, Integrity, Objectivity, Accountability, Openness, Honesty, Leadership.'},
  {act:'GGM · Strategies',q:'The GGM framework integrates two basic strategies to promote good governance. These are:',opts:['A. Legal approach and Medical approach.','B. Discipline-based approach and Values-based approach.','C. Ombudsman approach and Financial approach.','D. International approach and Local approach.'],ans:1,exp:'GGM integrates a Discipline-based approach (top-down: sanctions, ombudsman) and a Values-based approach (bottom-up: ethical framework, code of conduct).'},
  {act:'GGM · Appendix 2',q:'The FIVE key areas of the pharmaceutical system focused on by the GGM Ethical Framework are:',opts:['A. Research, Development, Marketing, Prescribing, Consumption.','B. Registration, Inspection, Promotion, Selection, Procurement.','C. Manufacturing, Distribution, Pricing, Selection, Disposal.','D. Patent, Manufacturing, Registration, Procurement, Distribution.'],ans:1,exp:'GGM Appendix 2 defines the 5 areas: Registration, Inspection, Promotion, Selection, and Procurement.'},
  {act:'GGM · Appendix 3',q:'According to the GGM Framework, the FOUR core moral values essential to good governance are:',opts:['A. Honesty, Integrity, Selflessness, Leadership.','B. Justice, Truth, Service to the Common Good, Trusteeship.','C. Objectivity, Accountability, Openness, Honesty.','D. Transparency, Fairness, Equity, Sincerity.'],ans:1,exp:'GGM Appendix 3 explicitly names 4 Core Moral Values: Justice, Truth, Service to the Common Good, and Trusteeship.'},
  {act:'GGM · Appendix 4',q:'Which of the following is an unethical practice that may lead to corruption in the pharmaceutical sector?',stmts:['i. Receiving gifts or sponsorships from pharmaceutical companies.','ii. Ordering medicines beyond actual clinical needs.','iii. Using evidence-based assessment criteria for drug registration.','iv. Disclosing conflicts of interest to the relevant authorities.'],opts:['A. i and ii only','B. iii and iv only','C. i, ii and iii only','D. i, ii, iii and iv'],ans:0,exp:'GGM: i (gifts/sponsorships ✓ unethical), ii (ordering beyond needs ✓ unethical). iii (evidence-based assessment) and iv (disclosing COI) are examples of GOOD governance practices.'}
]};

